using FilamentDbApp.Models;
using System.Globalization;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace FilamentDbApp.Services.Reporting;

public sealed class PublicManufacturerReportPublishingService
{
    public static IReadOnlyList<string> PublicFieldAllowlist { get; } = new[] { "ManufacturerSlug", "Manufacturer", "ManufacturerWebsite", "ProductLines", "MaterialTypes", "MaterialsWithResults", "CompleteProfiles", "MaterialsWithMsrp", "MaterialsWithVideo", "PublicBenchmarkManufacturers", "GlobalManufacturerRank", "AverageOverallScore", "PortfolioLeader", "StrongestAxis", "CategoryPositions", "Materials", "BaseMaterial", "Position", "ScoredProducts", "MaterialId", "MaterialName", "ProductLine", "Reinforcement", "TestCoverage", "EngineeringAxes", "OverallScore", "TensileScore", "ImpactScore", "StiffnessScore", "ConsistencyScore", "LayerAdhesionScore", "MsrpUsdPerKg", "ProductUrl", "VideoReviewUrl" };
    private static readonly string[] Forbidden = { "\"SupplierUrl\"", "\"PurchasedFrom\"", "\"PurchaseId\"", "\"InventoryId\"", "\"StorageLocation\"", "\"BatchNumber\"", "\"LandedCost", "\"Notes\"", ".sqlite" };

    public PublicManufacturerPublicationResult Build(PublicManufacturerReportModel model, DateTime generatedAt, string version, string title)
    {
        var slug = PublicComparisonReportPublishingService.SafeSlug(model.ManufacturerSlug);
        if (string.IsNullOrWhiteSpace(slug) || model.Materials.Count == 0) throw new InvalidOperationException("A public manufacturer report requires a stable slug and at least one allowlisted MaterialID.");
        var directory = $"reports/manufacturers/{slug}";
        return new PublicManufacturerPublicationResult { RelativeDirectory = directory, Html = Html(model, generatedAt, version, title, directory), Manifest = $"3DPIceland Public Manufacturer Report\nVersion: {version}\nGenerated: {generatedAt:O}\nManufacturer: {model.Manufacturer}\nStable relative directory: {directory}\nCanonical HTML: index.html\nPDF from canonical HTML: report.pdf\nMetadata: report-metadata.json\nAssets: assets/\nPublic field allowlist: {string.Join(", ", PublicFieldAllowlist)}\n", MetadataJson = JsonSerializer.Serialize(new { schema = "3dpiceland.public-manufacturer-report.v1", version, generatedAt = generatedAt.ToString("O", CultureInfo.InvariantCulture), reportKey = "manufacturer", stableRelativeDirectory = directory, canonicalHtml = "index.html", pdf = "report.pdf", publicFieldAllowlist = PublicFieldAllowlist, publicData = model }, new JsonSerializerOptions { WriteIndented = true }) };
    }

    public PublicComparisonVerificationResult Verify(PublicManufacturerReportModel model, PublicManufacturerPublicationResult result)
    {
        var payload = string.Join("\n", result.Html, result.Manifest, result.MetadataJson);
        var ids = model.Materials.Select(x => x.MaterialId).ToList();
        var passed = result.RelativeDirectory == $"reports/manufacturers/{PublicComparisonReportPublishingService.SafeSlug(model.ManufacturerSlug)}" && ids.Count > 0 && ids.Distinct(StringComparer.OrdinalIgnoreCase).Count() == ids.Count && PublicFieldAllowlist.All(x => result.MetadataJson.Contains($"\"{x}\"", StringComparison.Ordinal)) && Forbidden.All(x => !payload.Contains(x, StringComparison.OrdinalIgnoreCase)) && !Regex.IsMatch(payload, @"(?<![A-Za-z0-9])[A-Za-z]:[\\/]") && result.Html.Contains("Manufacturer overview and public global position", StringComparison.Ordinal) && result.Html.Contains("Category position by base material", StringComparison.Ordinal) && result.Html.Contains("Overall leaders", StringComparison.Ordinal) && result.Html.Contains("Consistency leaders", StringComparison.Ordinal) && result.Html.Contains("Layer adhesion", StringComparison.Ordinal) && result.Html.Contains("Engineering methodology whitepaper", StringComparison.Ordinal) && result.Html.Contains("assets/3dp-iceland-labs-logo-pdf.jpg", StringComparison.Ordinal);
        return new PublicComparisonVerificationResult { Passed = passed, Detail = passed ? $"Allowlisted manufacturer report ready at {result.RelativeDirectory}" : "Public manufacturer route, membership, allowlist, exclusion or content verification failed" };
    }

    public static string BuildPreviewIndex(IEnumerable<PublicManufacturerReportModel> models, DateTime at) => $"<!doctype html><html><head><meta charset=\"utf-8\"><title>Public Manufacturer Reports</title><style>body{{font-family:Segoe UI,Arial;margin:32px;background:#f1f5f9}}main{{max-width:900px;margin:auto;background:#fff;padding:28px;border-radius:16px}}article{{border-top:1px solid #cbd5e1;padding:12px}}a{{color:#1d4ed8;font-weight:700}}</style></head><body><main><h1>Public Manufacturer Reports</h1><p>Generated {at:yyyy-MM-dd HH:mm:ss}</p>{string.Join("", models.OrderBy(x => x.Manufacturer).Select(x => $"<article><h2>{H(x.Manufacturer)}</h2><p>{x.Materials.Count} allowlisted materials</p><a href=\"reports/manufacturers/{H(x.ManufacturerSlug)}/index.html\">Open HTML</a> &middot; <a href=\"reports/manufacturers/{H(x.ManufacturerSlug)}/report.pdf\">Open PDF</a></article>"))}<p>Local preview only. Nothing has been uploaded.</p></main></body></html>";

    private static string Html(PublicManufacturerReportModel m, DateTime at, string version, string release, string directory)
    {
        return PublicReportScreenThemeService.Apply(ApplyCanonicalPrintLayout(HtmlCore(m, at, version, release, directory)));
    }

    private static string HtmlCore(PublicManufacturerReportModel m, DateTime at, string version, string release, string directory)
    {
        var categories = string.Join("", m.CategoryPositions.Select(x => $"<tr><td>{H(x.BaseMaterial)}</td><td>{H(x.Position)}</td><td>{H(x.AverageOverallScore)}</td><td>{x.ScoredProducts}</td></tr>"));
        var materials = string.Join("", m.Materials.Select(x => $"<tr><td>{H(x.MaterialId)}</td><td>{H(x.MaterialName)}</td><td>{H(x.ProductLine)}</td><td>{H(x.BaseMaterial)}</td><td>{H(x.Reinforcement)}</td><td>{H(x.TestCoverage)}</td><td>{x.EngineeringAxes}/5</td><td>{H(x.OverallScore)}</td><td>{H(x.TensileScore)}</td><td>{H(x.ImpactScore)}</td><td>{H(x.StiffnessScore)}</td><td>{H(x.ConsistencyScore)}</td><td>{H(x.LayerAdhesionScore)}</td><td>{H(x.StrongestAxis)}</td><td>{(string.IsNullOrWhiteSpace(x.MsrpUsdPerKg) ? "n/a" : "$" + H(x.MsrpUsdPerKg))}</td><td>{Link(x.ProductUrl, "Product page")}</td><td>{Link(x.VideoReviewUrl, "Video review")}</td></tr>"));
        var charts = Chart("Overall leaders", m.Materials, x => x.OverallScore) + Chart("Consistency leaders", m.Materials, x => x.ConsistencyScore);
        return $"<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>{H(m.Manufacturer)} Manufacturer Report</title><style>body{{font-family:Segoe UI,Arial;margin:0;background:#f1f5f9;color:#0f172a}}main{{max-width:1280px;margin:30px auto;background:#fff;padding:30px;border-radius:18px}}header,.cards,.charts{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}}header{{border-bottom:3px solid #0f172a}}img{{width:180px}}.cards{{grid-template-columns:repeat(4,1fr);margin:20px 0}}.card,.chart,.note{{border:1px solid #cbd5e1;border-radius:12px;padding:14px}}.value{{font-size:22px;font-weight:800}}table{{width:100%;border-collapse:collapse;margin:12px 0 24px}}th,td{{padding:8px;border-bottom:1px solid #e2e8f0;text-align:left}}.bar{{display:grid;grid-template-columns:1fr 1fr 65px;gap:8px;margin:9px 0}}.track{{height:14px;background:#e2e8f0;border-radius:99px;overflow:hidden}}.fill{{height:100%;background:#0f172a}}a{{color:#1d4ed8}}@media(max-width:800px){{header,.cards,.charts{{grid-template-columns:1fr}}}}@media print{{body{{background:#fff}}main{{margin:0;padding:0}}.chart{{break-inside:avoid}}}}</style></head><body><main><header><div><strong>Public manufacturer report</strong><h1>{H(m.Manufacturer)}</h1><p>Portfolio coverage, product-level engineering context and comparative public manufacturer positioning.</p></div><div><img src=\"assets/3dp-iceland-labs-logo-pdf.jpg\"><p>{H(version)} - {H(release)}<br>{at:yyyy-MM-dd HH:mm:ss}</p></div></header><div class=\"note\"><strong>Public-data contract:</strong> portfolio statistics and positions use only explicitly allowlisted MaterialIDs and existing Verified Material Summary scores. No measurement or score is recalculated.</div><div class=\"cards\"><div class=\"card\"><div>Public materials</div><div class=\"value\">{m.Materials.Count}</div></div><div class=\"card\"><div>Product lines</div><div class=\"value\">{m.ProductLines}</div></div><div class=\"card\"><div>Material types</div><div class=\"value\">{m.MaterialTypes}</div></div><div class=\"card\"><div>With results</div><div class=\"value\">{m.MaterialsWithResults}</div></div><div class=\"card\"><div>Complete profiles</div><div class=\"value\">{m.CompleteProfiles}</div></div><div class=\"card\"><div>Average overall</div><div class=\"value\">{H(m.AverageOverallScore)}</div></div><div class=\"card\"><div>Public global rank</div><div class=\"value\">{H(m.GlobalManufacturerRank)}</div></div><div class=\"card\"><div>Benchmark manufacturers</div><div class=\"value\">{m.PublicBenchmarkManufacturers}</div></div></div><h2>Manufacturer overview and public global position</h2><table><thead><tr><th>Materials</th><th>Product lines</th><th>Types</th><th>With results</th><th>Complete</th><th>Average overall</th><th>Global rank</th><th>Portfolio leader</th><th>Strongest axis</th><th>With MSRP</th><th>With video</th></tr></thead><tbody><tr><td>{m.Materials.Count}</td><td>{m.ProductLines}</td><td>{m.MaterialTypes}</td><td>{m.MaterialsWithResults}</td><td>{m.CompleteProfiles}</td><td>{H(m.AverageOverallScore)}</td><td>{H(m.GlobalManufacturerRank)}</td><td>{H(m.PortfolioLeader)}</td><td>{H(m.StrongestAxis)}</td><td>{m.MaterialsWithMsrp}</td><td>{m.MaterialsWithVideo}</td></tr></tbody></table><div class=\"note\"><strong>Manufacturer website:</strong> {Link(m.ManufacturerWebsite, "Open manufacturer website")}</div><h2>Category position by base material</h2><table><thead><tr><th>Base material</th><th>Public manufacturer position</th><th>Average overall</th><th>Scored products</th></tr></thead><tbody>{categories}</tbody></table><div class=\"charts\">{charts}</div><h2>Product-level engineering context</h2><table><thead><tr><th>MaterialID</th><th>Material</th><th>Product line</th><th>Type</th><th>Reinforcement</th><th>Coverage</th><th>Engineering axes</th><th>Overall</th><th>Tensile</th><th>Impact</th><th>Stiffness</th><th>Consistency</th><th>Layer adhesion</th><th>Strongest axis</th><th>MSRP USD/kg</th><th>Product</th><th>Video</th></tr></thead><tbody>{materials}</tbody></table><div class=\"note\">Results are comparative 3DPIceland measurements and do not replace manufacturer datasheets or accredited laboratory testing.</div><p><a href=\"https://iskort.is/3dp/index.html#methodology\">Testing methodology</a> &middot; <a href=\"https://iskort.is/3dp/3DPIceland_Labs_Mechanical_Testing_Methodology_v1.0.pdf\">Engineering methodology whitepaper</a> &middot; <a href=\"report.pdf\">Download PDF</a></p><footer>Stable public path: {H(directory)}/</footer></main></body></html>";
    }
    private static string ApplyCanonicalPrintLayout(string html)
    {
        const string printCss = "@media print{body{background:#fff}main{max-width:none;margin:0;padding:0}header{grid-template-columns:repeat(2,minmax(0,1fr))!important}.cards{grid-template-columns:repeat(4,1fr)!important}.charts{grid-template-columns:repeat(2,minmax(0,1fr))!important}.chart{break-inside:avoid}table{font-size:8px;table-layout:auto}th,td{padding:4px;white-space:normal;overflow-wrap:anywhere}}/* 3DP-PUBLIC-PRINT-LAYOUT-v42.8.3 */";
        return html.Replace("</style>", printCss + "</style>", StringComparison.Ordinal);
    }
    private static string Chart(string title, IEnumerable<PublicManufacturerMaterialModel> rows, Func<PublicManufacturerMaterialModel,string> pick) { var items=rows.Select(x=>(x.MaterialName,N:Number(pick(x)))).Where(x=>x.N.HasValue).Select(x=>(x.MaterialName,N:x.N!.Value)).OrderByDescending(x=>x.N).Take(10).ToList(); if(items.Count==0)return $"<section class=\"chart\"><h3>{H(title)}</h3><p>n/a</p></section>"; var max=Math.Max(1,items.Max(x=>x.N)); return $"<section class=\"chart\"><h3>{H(title)}</h3>{string.Join("",items.Select(x=>$"<div class=\"bar\"><div>{H(x.MaterialName)}</div><div class=\"track\"><div class=\"fill\" style=\"width:{(x.N/max*100).ToString("0.#",CultureInfo.InvariantCulture)}%\"></div></div><div>{x.N.ToString("0.#",CultureInfo.CurrentCulture)}/100</div></div>"))}</section>"; }
    private static double? Number(string? s){var m=Regex.Match(s??"",@"-?\d+(?:[.,]\d+)?");return m.Success&&double.TryParse(m.Value.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out var n)?n:null;}
    private static string Link(string? s,string label)=>Uri.TryCreate(s,UriKind.Absolute,out var u)&&(u.Scheme=="http"||u.Scheme=="https")?$"<a href=\"{H(u.AbsoluteUri)}\">{H(label)}</a>":"n/a";
    private static string H(string? s)=>WebUtility.HtmlEncode(s??"");
}
